import{_ as l,l as n,o as e,c as o,v as i,p as s,x as r,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"策略交易者与噪声交易者","description":"","frontmatter":{"title":"策略交易者与噪声交易者","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/strategic-noise-traders.md","filePath":"quant/strategic-noise-traders.md","lastUpdated":1789023840000}'),p={name:"quant/strategic-noise-traders.md"};function h(u,a,E,A,_,f){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="策略交易者与噪声交易者" tabindex="-1">策略交易者与噪声交易者 <a class="header-anchor" href="#策略交易者与噪声交易者" aria-label="Permalink to &quot;策略交易者与噪声交易者&quot;">​</a></h1><div class="epigraph"><p>若流动性交易者也能选择何时来，他们会避开被知情者收割的时段，或挤进同一时段互相掩护。噪声不再是外生的 $\\sigma_u$，深度和日内形态一起被决定。</p><footer>—— Admati and Pfleiderer, A Theory of Intraday Patterns: Volume and Price Variability, Review of Financial Studies, 1988</footer></div><p><a href="/quant/price-efficiency-measures">方差比</a>把暂时成分当成收益的残差。缺口是：制造残差的「噪声交易者」若会优化，残差就不是残差。Kyle 把 \\(u\\) 当外生；Admati 与 Pfleiderer（1988）让非知情者选择在哪一期集中交易，Black（1986）把噪声本身写成市场存在的条件。本课补策略性流动性交易，不重推单期 \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外生噪声保证知情者有掩护、做市商有对手。一旦非知情者可以选择时点，他们有动机：(i) 避开信息不对称严重的期，以免被收割；(ii) 与其他非知情者挤在同一期，用厚度降低 \\(\\lambda\\)。知情者预见到聚集，也会选择在厚的时段释放信息。均衡可以出现内生的「热闹期」：成交量大、波动大、但单位流量的冲击未必更大。问题是：日内成交量与波动的共同高峰，能否在没有外生时钟新闻的情况下被这种聚集产生。</p><p>Black 的要点更先验：若没有把价格推离价值的噪声，知情者无法隐蔽，市场关闭。策略噪声是把这句话变成博弈。</p><h3 id="谁在优化、目标是什么" tabindex="-1">谁在优化、目标是什么 <a class="header-anchor" href="#谁在优化、目标是什么" aria-label="Permalink to &quot;谁在优化、目标是什么&quot;">​</a></h3><p>Admati–Pfleiderer 区分必须交易的流动性交易者（discretionary 在日内择时，non-discretionary 不能等）与知情者。择时者最小化被收割的成本，等价于寻找深度最大的期。做市商仍零利润定价。这与 Grossman–Miller 的「是否在场」不同：这里是客户侧择时，不是做市商进入。</p><p><span class="marginnote">Kyle（1985）的噪声是需求冲击；Kyle（1989）的不完全竞争知情者提交需求函数，对手方仍可以是噪声。策略噪声与策略知情是两个方向，不要合成一个「大家都策略」的模糊模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把交易日分成若干期，每期一个 Kyle 式批量。择时流动性交易者分配各期的 \\(u_n\\)，总流动性需求给定。均衡时他们集中在少数期，使那些期的 \\(\\sigma_u\\) 变大，\\(\\lambda\\) 变小；知情者的交易强度随 \\(\\sigma_u\\) 上升，信息释放也集中。结果：量与价格波动在同一期升高。这是对 U 型日内形态的一条理论，不是唯一条——开收盘还有制度性拍卖与存货。</p><p>比较静态：不能择时的流动性交易越多，聚集动机越弱，形态被抹平。知情者人数增加，抢信息租金，热闹期的信息含量上升，择时者的好处下降。</p><h3 id="噪声交易者不是非理性的同义词" tabindex="-1">噪声交易者不是非理性的同义词 <a class="header-anchor" href="#噪声交易者不是非理性的同义词" aria-label="Permalink to &quot;噪声交易者不是非理性的同义词&quot;">​</a></h3><p>Black 的噪声包括误解与外生需求。Admati–Pfleiderer 的择时者完全理性，只是没有私有信息。经验上把「散户」叫做噪声，必须声明是没有信息还是不会择时。会择时的非知情资金（指数再平衡、到期滚动）恰恰会制造可预测的量峰，那是策略噪声，不是随机 \\(u\\)。</p>',14)),(e(),s(m,null,{default:r(()=>[c(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Liq%5B%22%E6%8B%A9%E6%97%B6%E6%B5%81%E5%8A%A8%E6%80%A7%E9%9C%80%E6%B1%82%22%5D%20--%3E%20Bunch%5B%22%E6%8C%A4%E8%BF%9B%E5%90%8C%E4%B8%80%E6%9C%9F%22%5D%0A%20%20Bunch%20--%3E%20SigU%5B%22%E8%AF%A5%E6%9C%9F%20%CF%83u%20%E5%8F%98%E5%A4%A7%22%5D%0A%20%20SigU%20--%3E%20Lam%5B%22%CE%BB%20%E4%B8%8B%E9%99%8D%E3%80%81%E6%B7%B1%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Inf%5B%22%E7%9F%A5%E6%83%85%E8%80%85%22%5D%20--%3E%20Bunch%0A%20%20Lam%20--%3E%20Vol%5B%22%E9%87%8F%E4%B8%8E%E6%B3%A2%E5%8A%A8%E5%85%B1%E5%90%8C%E5%8D%87%E9%AB%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩护是公共品。每个择时者希望别人先去制造厚度，自己跟在厚的一期。均衡聚集是协调：一旦某期被预期为厚，所有人的最优是去那里。这与银行挤兑相反的「挤入」。市场设计可以提供协调装置——开收盘竞价、到期日——把策略噪声正规化。连续限价簿上，聚集表现为某些时钟的队列变厚、价差变窄。</p><p>对效率度量：热闹期 VR 与冷清期不同。把全日 VR 当效率，会平均掉策略噪声的日内结构。对执行：故意和指数再平衡挤在一起，是在买别人的 \\(\\sigma_u\\)，这是 Kyle 比较静态的操作版。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>离散期批量、每期重建线性 Kyle，忽略限价簿上的排队与撤单。真实新闻时钟（宏观公告）是外生聚集，与本模型的内生聚集纠缠。知情者若信息会过期（公告即将公开），他们不能等热闹期，聚集被打破。噪声若其实相关于价值（不是纯流动性），掩护变成额外的逆向选择。</p><p><span class="marginnote">「把单子拆到量最大的时候」并不总是降低冲击：若大家都这么做，该时点的知情密度也可能最高。Admati–Pfleiderer 均衡里量峰同时是信息峰。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略性流动性交易者会挤进同一时段互相掩护，内生出量与波动的高峰。</li><li>噪声在 Kyle 里是外生参数，在 Admati–Pfleiderer 里是博弈对象；Black 说明没有噪声则隐蔽与市场难以维持。</li><li>量峰可以同时是信息峰，执行上「跟量」不必更安全。</li><li>出处：Admati and Pfleiderer, <em>Review of Financial Studies</em>, 1988；概念见 Black, <em>Journal of Finance</em>, 1986；单期掩护见 Kyle, 1985。</li></ul>',8))])}const q=l(p,[["render",h]]);export{P as __pageData,q as default};
